INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (576,'zhTW','喂，$G哥們:妹子！雖然我看不見，但你這個$G小子:小姑娘一進港口我就聞出你的味道來啦。$B$B我的眼睛還能找回來嗎？船長知道我的眼睛落在那幫骯髒的血帆海盜手裡以後大罵了我一頓。$B$B對我這樣的瞭望員來說，沒眼睛的日子可真是太悲慘了！我現在都已經習慣了住在瞭望臺上……要是以後我再也看不見了，非得被髮配去洗船艙不可。',0);
