INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (662,'zhTW','你的打撈工作進行得如何了，$N？我們必須從處女號和銀松之靈號裡取回那些航海圖和日誌。$B$B如果那些寶貴的資訊落入敵人手裡，艦隊指揮官絕對會讓我們吃不了兜著走的。$B$B更確切的說，這關係到我們能否從現在的糟糕處境中擺脫出來。',0);
