INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (679,'zhTW','我看你的勇氣最終還是消退了。我的直覺似乎是對的：你一直都是在虛張聲勢而不具備真正的實力。$B$B要嘛帶著野獸的頭顱回來見我，要嘛就永遠都別回來。',0);
