INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (680,'zhTW','奧卡拉爾就在阿拉索之塔附近出沒。殺掉他就能阻止巨魔對落錘村的襲擊，也能保住我丈夫的生命。$B$B你的眼睛告訴我，在你的心中已經認定我是個軟弱甚至不光彩的懦弱者，因為我過於沉默。但是總有一天，你會理解我所做的一切的。也許到那時，你就會理解一種不同於以往的力量與榮耀。$B$B請按我說的去做，殺了奧卡拉爾。',0);
