INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (691,'zhTW','$N，你弄到我要的東西了嗎？$B$B<克里汀一邊唸唸有詞，一邊在他的日記本上作了些筆記。>$B$B如果我的研究工作是正確的話，那麼你可以在枯木巨魔身上找到獠牙，在枯木巫醫身上找到醫藥包，而最強大的枯木暗影獵手應該隨身帶著小刀。不過，只有當你和他們戰鬥之後，才能知道哪個暗影獵手擁有一把小刀。',0);
