INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (710,'zhTW','這個地區對於——你能拿著這些東西在這裡站一會嗎？對，就像那樣，面向那邊。嗯，我說到哪兒啦……哦，對，這個地區對於測試我的新專案來說實在是太完美啦。充足的原材料，開闊的空地……對於一個充滿智慧和靈感的發明家來說已經是很棒了。',0);
