INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (1045,'zhTW','你殺掉蘭恩了嗎，我的朋友？$B$B他甚至沒有資格去憎恨暗夜精靈。他的仇恨比我更加強烈，但他的思想已不再受他自己的控制。對於森林中的所有生物而言，他都是一個巨大的威脅。',0);
