INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (1046,'zhTW','哨兵部隊在梣谷竭盡全力地戰鬥著，但是多虧了像你一樣的$r，我們才保住了這片原本就屬於我們的土地。',0);
