INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (1053,'zhTW','除非那些高層官員被剷除，否則修道院中的墮落就不會停止。$B$B以聖光的名義，去殺掉高階審判官懷特邁恩，血色十字軍指揮官莫格萊尼，十字軍的勇士赫洛德和馴犬者洛克希。一旦除掉了他們，也許十字軍將會重新迴歸他們神聖的創立宗旨。那時十字軍才會成為一支無堅不摧的正義力量。$B$B從南海鎮出發吧，去完成你的使命！',0);
