INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (1148,'zhTW','啊，$N，很久不見了，我能為你做些什麼嗎？看來你最近經過了不少戰鬥的洗禮。你經歷的戰鬥越多，你的經驗就越豐富，你也會變得越發強大。',0);
