INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (1243,'zhTW','在這片森林裡旅行可不太安全，$N。小心為上，如果你看到任何可疑或者危險的東西，請立刻向守夜人報告。不要試圖自己去解決問題，否則出了什麼事情我們可無法負責。$B$B不過你我都知道你根本不會在意我的話，而且會不擇手段與黑暗中的怪物搏鬥，不是嗎？哈哈，是呀，你們這些冒險者都是一樣的。',0);
