INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (1424,'zhTW','沒人知道阿塔哈卡神廟內現在潛伏著何種黑暗邪惡的力量，但我們都能感覺到那裡聚集了強大的魔法能量。$B$B我們必須儘可能多地瞭解這種魔法，或許阿塔萊的法術對我們部落是有用處的。$B$B一旦你在淚水之池收集到了足夠的阿塔萊神器，我就能瞭解到那群巨魔究竟施放了怎樣的法術，以及那裡到底發生了多麼恐怖的事情。',0);
