INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (1458,'zhTW','薩特是一種卑劣的畜牲，傳說他們曾和暗夜精靈有一種說不清道不明的關係，不過我不是很相信那些說法。$B$B我想這樣的說法大概源於很多年前，曾有個暗夜精靈讓薩特捲入了戰爭中吧。這個世界真是越來越危險了……',0);
