INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (1469,'zhTW','你總算回來了，$N。好久沒見了，我還以為你已經把我的事視l悀F呢。$B$B你找到那個獅鷲騎士了嗎？他有沒有告訴你些什麼？',0);
