INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (1470,'zhTW','你現在的力量實在是太弱小了，但是我覺得你能夠感受到即將發生的事情。$B$B擁有這種力量之後，即使是死去的人也能感受到生命的氣息。',0);
