INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (1473,'zhTW','埃加林是我的老師，他曾教我召喚虛無行者的方法。他很偉大，他只需要用一個眼神就可以操控他召喚出來的虛無行者。$B$B而當輪到我來進行召喚的時候，我過分的自信給我帶來了不幸。不要輕視你還不能完全控制的這種力量，$N，即使你保持著警惕，它們還是隨時有可能將你吞噬。',0);
