INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (1474,'zhTW','魅魔擁有能穿越虛無的強大力量，是最危險的生物之一，她經常將弱者們玩弄於股掌之間。$B$B從現在開始，你得永遠記住這一點。',0);
