INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (1475,'zhTW','我已經不能再勝任一個冒險者的工作了，所以我希望你能幫忙，$N，幫我為探險者協會完成這最後的任務吧。如果我這身老骨頭還有力氣闖入悲傷沼澤、潛進神廟裡的話，我肯定會和你並肩作戰的。$B$B儘管我的自尊讓我很難開口來要求你的幫助，但我的年紀讓我不得不這麼做。$B$B拜託你了，$N。我想在完成了探險者協會交給我的最後一個任務之後就光榮退休。',0);
DELETE FROM `quest_request_items_locale` WHERE `ID` = 1476 AND `locale` = 'zhTW';
