INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (1481,'zhTW','別帶錯的頭皮給我，$C。如果用錯材料的話，可是會要我們的命的。這個惡魔領主的身上可能有很多法術可以用來殺死那些想偵測他的人。$B$B命運已經讓我品嚐過那樣的苦楚了。',0);
