INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (1482,'zhTW','我已經都準備好，就等神諭水晶了，$C。找到並除掉阿茲雷索克領主將為大酋長帶來一個巨大的好處。我們得好好合作，儘快完成這件事，這樣無論對我們還是酋長都有好處。',0);
