INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (1485,'zhTW','控制住你用魔法召喚出來的生物是非常重要的一件事情。你得弄清楚，學習術士的魔法與行事之道並非是什麼有趣的事情，若是在你做好準備之前，就教導你過於高深的知識是會讓你丟掉性命的。',0);
