INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (1487,'zhTW','$N，我們這些納拉雷克斯的信徒需要你的幫助。我們的人數隨著領袖陷入了他扭曲的夢魘而不斷地減少。因此，我們已經沒有足夠的力量去對付那些佔據了洞穴的墮落生物了。$B$B我請求你，$C，進入那些洞穴，把那些該死的變異生物都殺光吧！',0);
