INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (1488,'zhTW','榮耀歸於部落，而死亡歸於吾敵，$N！$B$B淒涼之地的惡魔領主比以前更具威脅性了，我希望以後去覲見大酋長的時候，每次都能向他報告好訊息，而不是像現在這樣……$B$B有些時候，我真希望只有半人馬需要對付。',0);
