INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (1498,'zhTW','你拿到鱗片了嗎，$N？除非你可以承受那些雷霆蜥蜴的猛烈攻擊，否則我不會給你任何好處的。',0);
