INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (1504,'zhTW','虛無行者是一種強大的生物。我現在還清晰地記得當年我與它戰鬥時的情景，$N。經過了這麼多年，我的虛無行者已經很少與我發生衝突了，我想這也許是它想讓我放鬆警惕的緣故吧。$B$B牢牢記住這一點，$N。',0);
