INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (1513,'zhTW','一看到魅魔，我的心臟就開始咆哮……但與此同時，我能感覺到我的靈魂正在迅速消逝，如海潮退卻一般地衰減。$B$B你要多加小心，我的朋友。',0);
