INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (1644,'zhTW','但願我丈夫約翰在鐵爐堡能有更好的運氣。他並不想把我和孩子們留下，自己一個人跑去那兒，不過他知道必須這麼做，他真是太善良了。$B$B前些年的生活還不錯，不過現在的日子越來越難過了。我們都能感覺到好像會有重大的變化發生，不過又有誰知道呢？',0);
