INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (1648,'zhTW','就算是這裡和整個艾澤拉斯的商人都願意幫忙，我們也無法得到足夠的材料為孤兒院的所有孩子們製作衣裳。請幫我收集一些亞麻布，好讓我的妻子力所能及地幫助孩子們。謝謝您，$N。$B$B如果走運的話，不久之後我就能回家見到我的妻子了。',0);
