INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (2821,'zhTW','我說過，如果你給我十張厚重的雪人毛皮，我就讓你在我的皮貨中選一件。我一向以品質為重，我保證你得到的是好東西！$B$B如果你找不到雪人，那麼我可以指點你一二，到被遺忘的海岸那邊去，向內陸走，它們就在深痕谷附近。',0);
