INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (2822,'zhTW','你能弄到十張厚重的雪人毛皮嗎？我的皮貨是無與倫比的，如果你有這種皮革的話，我就給你製作一件樣品。$B$B如果你找不到那些雪人，我可以給你一些指點。從這裡往西，它們就在被遺忘的海岸裡，靠近深痕谷的地方。',0);
