INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (2857,'zhTW','我需要那些外套和頭罩，另外還需要一株野葡萄，然後我就會把蠻皮盔帽的製作方法告訴你。$B$B防護頭部的裝備是冒險者們垂涎已久的，無論是簡單的頭帶還是一頂密閉的盔帽，無論其外觀如何，製造有價值的頭部裝備的道理是恆久不變的。',0);
