INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (2858,'zhTW','在你學習這個圖樣以前，你必須把褲子、靴子和野葡萄給我拿來，$N。你找到這些東西了嗎？$B$B從我們學會製作第一雙靴子起，我們便開始懂得如何掌握靴子的舒適性與功能性之間的尺度。只有兼顧兩樣，我們才能夠製造出令穿著者忘記疲勞的靴子，我們的靴子絕對會讓那些劣質的同類產品無地自容。',0);
