INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (2859,'zhTW','你弄到龜鱗頭盔和護腕了嗎？另外不要忘記我還要兩株野葡萄。$B$B現在，你已經開始意識到蠻皮護脛潛在的能量了。一件擁有無窮應用潛力的護甲對於一個皮革匠來說是無價的，唯一的瓶頸是製作這些護甲所需要的原料——而不是成品的品質！',0);
