INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (2947,'zhTW','嘿，朋友，放輕鬆點——我是個有頭有臉的商人！肯定是郵差忘了把帳單給我送來……等等……你不是我的房東。$B$B好吧，你當然不是來耍我的！你是來尋找鐵爐堡最好的珠寶商的吧，我可絕對不會製作被詛咒的珠寶哦！絕對不會！$B$B嗯……你需要什麼？',0);
