INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (2970,'zhTW','辛達爾需要花些時間準備，但我們已經殺掉許多敵人了。恐怖圖騰氏族對我們深惡痛絕，他們就像毒蛇一樣到處追捕我們。$B$B你要當心一點，$N……你插手了，他們也會來抓你。',0);
