INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (3112,'zhTW','啊，又一個身負重任的地精拿來了備忘錄……真有趣。$B$B不，不，小傢伙，我不是在嘲笑你，我尊重你的頑強，真的。要是鐵爐堡被黑鐵矮人佔據的話我同樣也會感到憤怒，所以不要認為我無法體會你的困境……',0);
