INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (3113,'zhTW','很高興看到你帶著我的便箋回來。抱歉，我把它偽裝成一份高階公函……我並沒有惡意，我相信包括我們兩個在內的所有盜賊都應該緊密地團結在一起。$B$B許多人都不認為我們這類人聚集在同一個城市裡是件好事，但我認為我們合作得很愉快，你說呢？',0);
