INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (3114,'zhTW','耶，看看這是誰，一個$r？如果你不介意的話，請大點聲說話。我喝麥芽酒之後耳朵有點不好使。',0);
