INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (3118,'zhTW','你好，$N。很高興你找到了我。我還在想你大概迷路了。$B$B自從我給你符記之後，幽影谷沒有發生什麼新的事情，但我會讓你去收集一些資訊。如果願意的話，你可以去和奧達希爾的其它居民談談。',0);
