INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (3381,'zhTW','我仍然在這裡執行主人吩咐的任務。我其實可以隨便要求你提供什麼東西來做為見到主人的代價，但是現在，我只要求每個旅人提供兩根羽毛來完成我精美的箭。$B$B如果你不夠小心的話，我可是會提價的。六枚金幣聽起來怎麼樣？$B$B就這樣了，我現在就要求那麼多。小心行事，我會暫時把價格保持在現在的水準。',0);
