INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (3792,'zhTW','你好，我們又見面了，$N。我的研究進展得相當順利，不果如果你還有5株晨光麥的話，我會很樂意地從你這兒購買的。呃……“樂意”在這裡只是一個修飾語罷了，和這些東西相處的時間越長，我就越發感到不太舒服。儘管如此，我的研究任務仍要求我必須認真對待工作，並盡力克服我這奇怪的心理作用。',0);
