INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (3841,'zhTW','你好啊，$C。$B$B可別被我所待的地方給糊弄了，我到這兒來可不是為了賽車……不是為了娛樂而來。$B$B我到千針石林是為了調查這片土地到底有多麼貧瘠。現在我要讓這裡的鹽礆地變成新鮮肥沃的土壤，使它獲得新生！也許我很快就要在這附近發現水源了。$B$B你有沒有覺得菲拉斯和千針石林之間的差異之大簡直令人感到匪夷所思？一定有什麼奇怪的魔法從中作祟……',0);
