INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (4129,'zhTW','基恩諾派你來的？$B$B我的心靈占卜能力讓我心力交瘁……我在牌桌上的損失也一樣。要塞裡的其它人都叫我“厄運之王”。沒有牌運……但在掌握自然的秘密方面運氣還不錯，大概就是如此吧。$B$B好吧，我當然可以幫你。這可能是我們找到拉斯卡爾的關鍵所在。如果你願意給我那把刀子，我們就可以開始了。',0);
