INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (4144,'zhTW','計劃是這樣的，$N：去收集一些血瓣花苗——你要知道，現在這種植物還沒有開始廣泛傳播其種子，所以儘快把它們給我弄來，然後我就能看看阿塔萊之霧可以幹些什麼……$B$B你也許會認為我復仇心很重……事實上，所有人都應該有這樣的權利！$B$B事實是這樣的，我知道離開這裡的路，但是除非拉瑞安承認我是對的，否則的話我就得永遠待在這裡！$B$B快點出發吧，找到那些血瓣花苗，然後就準備看好戲吧！',0);
