INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (4508,'zhTW','他們都是笨蛋，$N！他們甚至沒有想到在自己的周圍潛藏著多麼可怕的威脅，他們對部落的仇恨最終會導致我們的毀滅！我不知道除了把他們直接丟到其中一個蠍巢以外，還有什麼關於異種蠍威脅的證據可以給他們？$B$B對不起，你有什麼訊息要給我嗎？',0);
