INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (4781,'zhTW','金錠，對，沒錯。給我拿一塊金錠來，我就可以幫你紡織出金線。不過呢，我建議你的目標應該是努力使自己變得更強大。最艱難的考驗還在前面呢。相信我……無論你認為自己的能力有多強，你都該追求更強。',0);
