INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (4783,'zhTW','淒涼之地可不是個友善的地方。納迦、巨人、薩特、燃燒軍團、好戰的半人馬部落……所有這些都使得這片區域危機四伏，所以你得加倍小心。$B$B就像我先前所說的一樣，這次任務不僅會考驗你的力量和智慧，還會考驗你的耐性。隨時保持警惕，$N。',0);
