INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (4801,'zhTW','在冬泉谷，你會與強大的霜刃豹戰鬥，這些猛獸擁有令人難以置信的速度和狡詐。如果你希望擁有霜刃豹的速度，就把你從它們身上找到的魂精交給我。$B$B記住，如果你想搜尋魂精的話，就必須隨身帶著瑪艾裡的容器。',0);
