INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (4802,'zhTW','在冬泉谷，你將與被稱為冬泉熊怪的墮落生物搏鬥，這些怪物擁有令人難以置信的力量。如果你想要獲得冬泉熊怪的力量，就把你從它們身上找到的魂精交給我。$B$B記住，如果你想搜尋魂精的話，就必須隨身帶著瑪艾裡的容器。',0);
