INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (4803,'zhTW','在冬泉谷，你會找到強壯無比的巨熊，這些裂齒熊有著很強的忍耐力。如果你想要獲得抵抗火焰的能力，就把你從裂齒熊身上找到的魂精交給我。$B$B記住，如果你想搜尋魂精的話，就必須隨身帶著瑪艾裡的容器。',0);
