INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (4805,'zhTW','在冬泉谷，你會與巨大的冰薊雪人戰鬥。他們的行動非常緩慢，但是厚厚的皮毛可以讓他們獲得超強的防禦力。如果你希望擁有躲避攻擊的能力，就把你從他們身上找到的魂精交給我。$B$B記住，如果你想搜尋魂精的話，就必須隨身帶著瑪艾裡的容器。',0);
