INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (5043,'zhTW','據說我們部族裡最強大的斥候有著無與倫比的準確度，而且任何盜賊<哼哼>在戰爭中都無法與他們的靈巧和迅捷媲美。$B$B給我弄四塊血巖裂片來，我就會讓你變得比任何野豬人都更加敏捷。',0);
