INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (5044,'zhTW','野豬人部族的薩滿和地卜師<鼻息聲>會召喚阿迦瑪甘的力量，以幫助他們進行戰爭和祭祀儀式，$C。$B$B要是你也希望給自己的法術附上擁有阿迦瑪甘的祝福，就給我弄四塊血巖裂片來，碎牙會幫助你的。<鼻息聲>',0);
