INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (5045,'zhTW','各種戰士<哼哼>都需要強大的精神力量。當所有希望都不復存在時，只有它能驅使你去完成更偉大的事業。這對<哼哼>鋼鬃野豬人來說並不是秘密。我們是一個有著共同信仰的部族——比起我們在戰鬥中所表現出的威力<哼哼>來說，我們更以能與阿迦瑪甘保持精神聯絡為榮。$B$B給我弄四塊血巖裂片來，我就會祝福你，讓你在戰鬥中充滿鬥志。<哼哼>',0);
