INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (5046,'zhTW','所有<哼哼>踏入戰場的勇士都需要保護。他們的骨骼必須強壯，他們的皮膚必須堅韌。<哼哼>我的部族也知道這點，為了讓我們與生俱來的鬃毛和皮膚有更好的防護效果，<哼哼>我們經常在上戰場之前請求阿迦瑪甘保護我們免受傷害。$B$B給我帶來四塊血石裂片，<哼哼>我就會賜給你同樣的保護。',0);
