INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (5052,'zhTW','我們的部族聚集在遍及貧瘠之地的荊棘旁，<豬哼聲>因為那種地方是神聖的，但它們都不如剃刀沼澤那般神聖。阿迦瑪甘的身體構成了剃刀沼澤的全部<豬哼聲>，但高地是最關鍵的，因為那個入口是由他巨大的嘴形成的！<豬哼聲>它會吞掉所有不忠於他的人，並把咀嚼後的屍體吐出來！<豬哼聲>$B$B阿迦瑪甘把肉體留下來保護我們，而且他還獻出了他的靈魂，讓我們來保護他。<豬哼聲>',0);
