INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (5096,'zhTW','對血色十字軍薄弱的防線進行突襲，這為我們贏取了向安多哈爾進軍的時間。我相信你是來此彙報勝利的訊息的！$B$B一旦你成功地完成了任務，我們很快就要開戰了。如果天災軍團和血色十字軍識破我們的計謀，以我們的實力是不可能同時與這兩方抗衡的。',0);
