INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (5507,'zhTW','啊，高尚的$C！你帶來我所要求的銀色黎明勇氣勳章了嗎？只要你把它們交給我，我就可以向你提供各種各樣的披肩了。',0);
