INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (5518,'zhTW','我製作巨魔裝所需要的材料中，巨魔鞣酸也許是最難找到的——我想也許你可以在這裡的樓上找到一些？不過很難說，因為我被拴在這裡寸步難行……$B$B不管怎樣，把我需要的東西給我拿來，我就會幫你製作一件巨魔裝，然後你就可以用它來欺騙克羅卡斯，因為他會以為你是自己人。',0);
