INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (5526,'zhTW','拿到淨化之匣後，我們不僅可以從世界上消除一股墮落的力量，而且可以謹慎理智地對其進行研究。也許我們可以找到與威脅艾澤拉斯的墮落力量抗衡的新方法。$B$B我知道米利會得到它的……',0);
