INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (5534,'zhTW','那麼，$N，符石在哪裡？你是個好的僱員，不是嗎？你來這裡是要幫我忙的吧？$B$B不要讓我後悔付錢給你。什麼？哦，我們之間沒有達成任何協定？哦，太好了……那麼你慢慢來吧——不過如果你浪費了很多時間的話，那是你的損失，不是我的。',0);
