INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (5535,'zhTW','你搜尋精靈貴族之魂的工作進行得怎麼樣了，$C？$B$B有很多事情使得整個艾澤拉斯都遭受了巨大的痛苦，但是因為某些原因，這些遊魂對所有人來說好像一場瘟疫。也許它們仍然還是渴望著獲得魔法的力量——這種渴望最終會引來燃燒軍團，我們知道這意味著什麼。',0);
