INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (5728,'zhTW','你找到他們了嗎，$N？我是說灼刃氏族的領袖。$B$B我知道暗影議會想要從我手中奪走奧格瑪以及整個部落，但是我還不清楚他們能以多快的速度滲透到這座城市裡來。這群叛徒擁有如此大的勢力……我們可以全力以赴，奮勇殺敵，直至筋疲力盡，但是情況並不會好轉多少。我必須讓我的探子更活躍一些。',0);
