INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (5801,'zhTW','你鑄造出骷髏鑰匙的主體部分了嗎？很抱歉你得自己掏錢來買這個模具，但是我們必須各盡所能地共同對抗天災軍團。一旦你把未完成的鑰匙交給我，你就可以開始準備鑄造鑰匙所需的最後一件物品了。$B$B雖然這並不簡單，但是你為了進攻安多哈爾所做的準備將會初見成效。你會看到的。',0);
