INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (6545,'zhTW','那麼，你是來給我傳達上面的命令的？看見你這樣體格健壯、意志堅定的新兵，我總是會感到很高興。$B$B要是你希望繼續在這裡待下去的話，最好儘快成長起來。納迦的威脅正在日益增長，$N。自從我到這兒之後，就開始著手研究對策，並在這個前哨站裡抵擋了他們的多次進攻。$B$B但是如果你也想要投入到對敵作戰中，就去跟這裡的其它人也談談吧。',0);
