INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (6701,'zhTW','我們與辛迪加交戰數年，他們戰鬥技藝極差，卻屢屢以數量取勝。單憑砍殺是不可能對他們的數量造成明顯影響的！$B$B不過我們發現，要削減辛迪加的人數，最好的辦法是竊取他們的紋章。誰丟失了紋章，他們的組織就會“處理”誰。$B$B去翻他們的口袋，把紋章交給我或是其它的守衛。$B$B你就從南邊的敦霍爾德城堡開始吧。',0);
