INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (6781,'zhTW','奧特蘭克山谷中的戰鬥永不停息，從鐵爐堡送來的補給並不能滿足我們軍隊的需要。$B$B如果你可以從戰場上收集護甲碎塊的話，那就把它們交給我吧！',0);
