INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (6801,'zhTW','我來自雷霆崖，$C。凱恩親自指示我在眼前這個艱難的時刻協助霜狼氏族。$B$B我們簡單明瞭地說吧，你必須擊倒我們的敵人，把他們的鮮血交給我。一旦我收集到了足夠的鮮血，召喚儀式就可以開始了。$B$B當元素之王衝入矮人的部隊中時，勝利就是我們的了。',0);
