INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (6826,'zhTW','你工作得很努力，$N，但是我們只是剛剛開始而已！$B$B我的馭風者部隊要在吃飽之後才能對敵人發起突襲！$B$B我的部隊在我們的空軍中實力排名第二，它們將對敵人最強的部隊發起進攻。因此它們也需要優質的食物，從雷矛士官那裡搶奪他們隨身攜帶的生肉吧。$B$B快點出發，勇士！',0);
