INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (7064,'zhTW','我原本想要自己去進行這場戰鬥，但是我們沒有選擇——我們需要更加強大的幫手，而艾澤拉斯的各個種族早已證明，只要他們團結起來就可以擊敗非常可怕的敵人。所以我尋求你的幫助。$B$B我希望這已經足夠了。$B$B作為雷姆洛斯的兄弟，札爾塔給這個世界帶來了無盡的痛苦，並最終導致了他自己的死亡。我只希望我們不會再造成更多的死亡。',0);
