INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (7066,'zhTW','你身上有墮落的氣味，$N……最近一段時間到這裡來的許多旅行者都是這樣。但是你身上的有所不同。你來這裡是有什麼事情要告訴我的嗎？你身上有一種讓我感覺非常熟悉的氣息，但是我不知道那是什麼。$B$B請你告訴我，你為什麼要來找我？',0);
