INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (7819,'zhTW','你好，$N！我們的符文布一直比較緊缺，如果你可以省出一些符文布來給我們的話，我們總是表示歡迎的。要是你可以再給我們20塊符文布，那麼我可以保證，你一定會因為對於幽暗城的貢獻而被大家認同。$B$B隨時歡迎你捐獻符文布。',0);
