INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (7941,'zhTW','$N，我必須要感謝你的幫助。我有很多的補給了，當然這裡面你幫了很大的忙，如果你可以帶更多的護甲片給我的話，我會很樂意用暗月馬戲團獎券來交換它們。',0);
