INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (7942,'zhTW','$N，你對我們真是太好了，一直不嫌疲倦的替我帶來這些貨物。我由衷地感謝你！$B$B雖然我們對於瑟銀零件的需求已經不像之前那麼大了，但是你仍然可以拿來給我，我還是會很樂意用它們來交換暗月馬戲團獎券的。',0);
