INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (7943,'zhTW','$N，我正在設計的東西將是繼諾莫瑞根被入侵後最可怕的事件！這要大力的感謝你以及你帶給我的小玩意兒。真是太太太感謝你了！$B$B雖然我已經不太需要了，但是……如果你可以從東瘟疫之地的蝙蝠身上取得更多的邪惡蝙蝠眼給我的話……我也許會給你更多暗月馬戲團獎券。',0);
