INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (8149,'zhTW','你到達光明使者烏瑟爾的墓碑，放下他的祭品了嗎？$B$B對經驗並不豐富的冒險家來說，這是一次危險的旅程。沿著穿越希爾斯布萊德的河流向北進入瘟疫之地是一條相對安全的道路。河流從悔恨嶺附近的湖泊發源，往西奔流進入群山，穿過寂靜的墳墓……那兒到處都是天災軍團的爪牙。',0);
