INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (8241,'zhTW','我沒時間跟你扯東扯西的，$r。現在是補充我們日益減少的熾熱助熔劑儲備的時候了。$B$B我需要的物品有：$B$B*燻火龍的鱗片。$B$B*鐵錠。$B$B*煤塊。$B$B凡是你能給我的，我都要！$B$B如果你想要跟兄弟會搞好關係的話，就最好快點去找。',0);
