INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (8334,'zhTW','你最好多瞭解一點生存的意義——還有生存的代價——早點知道比較好。身為一個血精靈，作困難的決定是你即將習慣的事。$B$B當天災軍團將我們的家園一分為二的時候沒有人伸出援手。是我們，我們自己重新振作，東山再起。',0);
