INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (8588,'zhTW','如果你只是要來這裡碎碎唸的話我可沒有時間，$C。有太多堆重皮需要儲存。等你至少有10張後再回來找我。',0);
