INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (8589,'zhTW','沒錯，$C，我還需要更多重皮。將軍和軍需官的需求似乎永無止盡。而這些跟飛艇管理員所要求的數量比起來更加微不足道！$B$B我需要收集雙倍的配額量。$N，幫我帶更多重皮來，越快越好！',0);
