INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (8591,'zhTW','$C，你可以看見我仍需要收集更多厚皮。我再次要求你協助這個任務，並且保證，如果你完成任務我們會肯定你的努力。$B$B時間就是金錢！帶著厚皮回來找我，我們就能完成準備去打仗！',0);
