INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (8601,'zhTW','為安其拉之戰做的準備繼續進行，$C。但是，要確定我們沒有落後，或至少不要成為造成落後的人，我要你再帶回另一批硬甲皮給我。這一次，儘量切割的乾淨一點，知道嗎？我還要浪費時間清理你上次給我的那批貨。',0);
