INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (8884,'zhTW','我們遠行者居所的騎兵巡邏隊奉命導正我們這塊美好土地上遭到的破壞。為達此目的我們會無所不用其極。$B$B我相信你已帶著我要你去收集的魚人頭顱回來？',0);
