INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (9266,'zhTW','你一定是對我們或我們的朋友做了什麼可怕的事，$N。無論如何，我是來提供你一個方法贏回我們的好感。$B$B你知道，冬泉谷還滿冷的。我們有這麼多的地精從別的城市過來，需要一些幫忙來保持溫暖。幫我帶一些符文布和煤炭來我就會幫你說點好話。不過要小心，我們的敵人不會對你的幫忙產生好感的。',0);
