INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (10352,'zhTW','我們現在接受毛料的捐贈。只要捐贈60塊毛料，達納蘇斯就會對你的慷慨行為表示感謝。我們只需要你捐贈60塊毛料就夠了，更多的毛料可以從其它志願者的捐贈獲得。$B$B如果你有60塊毛料並願捐獻的話，那現在就可以給我了。',0);
