INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (10354,'zhTW','和其它紡織材料一樣，我們的絲綢庫存也已經降到了歷史最低點。如果有足夠的補給，我們就可以達成預期的目標。$B$B如果你願意將絲綢作為禮物送給我們的話，那你在我們中的地位無疑將大大提升！那麼，要是你有60塊絲綢並且願意把它們捐出來，那現在就可以給我了。',0);
