INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (10693,'zhTW','如果如果你有榮譽徽章，我可以用它來幫助你提高在暴風城的知名度。$B$B請注意，你最好一次交給我十枚榮譽徽章，這樣你的知名度會獲得更大的提高。我們提供針對一枚榮譽徽章的交換服務是為了方便那些沒有足夠榮譽徽章的冒險者。$B$B總之，如果你想要用榮譽徽章來換取聲望的話，我隨時在這裡等著你。',0);
