INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (10694,'zhTW','完成了自己的任務並得到榮譽徽章的冒險者可以把他們的徽章交給我，你每次把10枚徽章交給我，我都可以用它們來顯著提升你在暴風城的聲望。當然，我也接受單枚徽章的交換申請，但是這對於聲望的提升效果就會遜色許多。雖然我們不會忘記每一位冒險者的努力，但是貢獻越大，回報就越大。$B$B如果你有足夠的榮譽徽章要給我的話，隨時來找我。',0);
