INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (11551,'zhTW','第一道障壁就橫攔在惡魔布魯塔魯斯的死亡之痕後方。阿格瑪司大門阻斷了死亡之痕後的道路。$B$B<奈蘇爾指著太陽之井的魔法複製模型。>$B$B把不朽者精華帶來給我，那隻能從這個世界最強大的生物身上取得！只要拿到精華，我的法師們就能夠將阿格瑪司拆解，徹底摧毀那道障礙，解開通往太陽之井的道路。',0);
