INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (10455,'zhTW','我說的難道不是實話嗎？林地潛獵山貓已經不僅對經過這條路的旅人構成威脅，對希瓦娜爾本身也是如此。$B$B牠們的死固然令人遺憾，但我們創造生命樹叢的初衷，正是要讓希瓦娜爾被一片充滿自然之美與寧靜的防禦性地帶所環繞。',0);
